import type { Question } from '../../lib/types'

export const serverless_containers_questions: Question[] = [
  { id: 'd3-svc-001', domain: 3, topics: ['Lambda', 'cold start', 'performance'], type: 'single', stem: 'A Lambda function written in Java experiences 3-second cold starts that affect user experience. What is the most direct way to eliminate cold starts?', options: [{ id: 'A', text: 'Increase Lambda memory allocation' }, { id: 'B', text: 'Enable Lambda Provisioned Concurrency — pre-warms function instances so cold starts are eliminated for provisioned capacity' }, { id: 'C', text: 'Use a smaller Lambda package' }, { id: 'D', text: 'Switch to Python runtime' }], correct: ['B'], explanation: 'Provisioned Concurrency initializes a specified number of Lambda execution environments in advance. These are ready to handle requests immediately with no cold start delay. Best for latency-sensitive applications.', distractors: { A: 'More memory speeds up initialization but doesn\'t eliminate cold starts.', C: 'Smaller packages reduce cold start duration but don\'t eliminate them.', D: 'Python has faster cold starts than Java but provisioned concurrency is the definitive solution.' } },
  { id: 'd3-svc-002', domain: 3, topics: ['Lambda', 'concurrency', 'limits'], type: 'single', stem: 'A Lambda function processes user requests and a traffic spike causes throttling errors. What type of concurrency limit applies per function and can be reserved?', options: [{ id: 'A', text: 'Account concurrency limit (1,000 per region default)' }, { id: 'B', text: 'Reserved concurrency — guarantees a set number of concurrent executions for a function and limits its maximum concurrency' }, { id: 'C', text: 'Burst concurrency (500-3,000 initial)' }, { id: 'D', text: 'Provisioned concurrency (pre-warmed instances)' }], correct: ['B'], explanation: 'Reserved concurrency serves two purposes: (1) guarantees the function can always get that many concurrent executions, and (2) limits the function from using more. Useful to protect other functions from one function consuming all account concurrency.', distractors: { A: 'Account limit (1,000 default, can be increased) is shared across all functions — not per-function.', C: 'Burst concurrency is the initial scaling rate — not a per-function reservation.', D: 'Provisioned concurrency pre-warms instances for cold start elimination — different from reserved concurrency.' } },
  { id: 'd3-svc-003', domain: 3, topics: ['Lambda', 'memory', 'CPU'], type: 'single', stem: 'A Lambda function processes large files and is slow despite optimized code. The function is currently allocated 256 MB. What should be adjusted?', options: [{ id: 'A', text: 'Increase the timeout limit' }, { id: 'B', text: 'Increase Lambda memory — CPU allocation scales proportionally with memory; more memory = more CPU' }, { id: 'C', text: 'Enable enhanced networking' }, { id: 'D', text: 'Use Lambda@Edge instead' }], correct: ['B'], explanation: 'Lambda CPU is not a separate configuration — it scales proportionally with memory. A function with 256 MB gets ~0.25 vCPU; 1,792 MB gets 1 full vCPU. For CPU-bound workloads, increase memory to get more compute.', distractors: { A: 'Timeout increase prevents timeout errors — doesn\'t speed up execution.', C: 'Lambda doesn\'t have enhanced networking configuration.', D: 'Lambda@Edge has memory limits (128MB-10GB) and is for CloudFront integration — not general compute scaling.' } },
  { id: 'd3-svc-004', domain: 3, topics: ['ECS', 'Fargate', 'task size'], type: 'single', stem: 'An ECS Fargate task needs 2 vCPU and 8 GB of memory. How is this configured in Fargate?', options: [{ id: 'A', text: 'Set instance type to c5.large' }, { id: 'B', text: 'Set task-level CPU (2048 CPU units = 2 vCPU) and task-level memory (8192 MB = 8 GB) in the task definition' }, { id: 'C', text: 'Fargate always uses fixed compute — cannot be configured' }, { id: 'D', text: 'Configure the container\'s minimum memory reservation only' }], correct: ['B'], explanation: 'Fargate uses task-level CPU and memory configuration. CPU is in units (1 vCPU = 1024 units). Valid combinations are specific (not arbitrary) — AWS defines valid CPU/memory pairs. The task runs on shared infrastructure sized to these specs.', distractors: { A: 'Fargate is serverless — no instance type selection; AWS manages the underlying EC2 instances.', C: 'Fargate absolutely supports CPU/memory configuration — it\'s the core sizing parameter.', D: 'Task-level CPU and memory must be set for Fargate tasks, not just container-level minimums.' } },
  { id: 'd3-svc-005', domain: 3, topics: ['Lambda', 'container images', 'size'], type: 'single', stem: 'A Lambda function requires a large number of Python libraries (500 MB+). ZIP packages are limited to 50 MB. What enables large Lambda deployments?', options: [{ id: 'A', text: 'Split the function into multiple smaller functions' }, { id: 'B', text: 'Deploy Lambda as a container image — supports up to 10 GB images stored in ECR' }, { id: 'C', text: 'Use Lambda Layers (250 MB limit per layer)' }, { id: 'D', text: 'Store libraries in S3 and download at runtime' }], correct: ['B'], explanation: 'Lambda supports container images up to 10 GB (uncompressed). Push the image to ECR, reference it in the function. Allows standard Docker tooling, custom runtimes, and large dependency sets well beyond ZIP limits.', distractors: { A: 'Splitting functions complicates architecture — container images solve the size limit directly.', C: 'Lambda Layers have a 250 MB limit (unzipped) — not enough for 500 MB+ dependencies.', D: 'Downloading libraries at runtime increases cold start time and is unreliable — container images are the correct solution.' } },
  { id: 'd3-svc-006', domain: 3, topics: ['EKS', 'node groups', 'managed vs self-managed'], type: 'single', stem: 'An EKS cluster needs worker nodes that AWS patches and manages automatically. What EKS node type provides this?', options: [{ id: 'A', text: 'Self-managed node groups — customer manages the EC2 instances' }, { id: 'B', text: 'EKS Managed Node Groups — AWS provisions, patches, and drains nodes during updates; handles rolling updates' }, { id: 'C', text: 'Fargate profiles for EKS — serverless, no node management at all' }, { id: 'D', text: 'AWS Batch with EKS integration' }], correct: ['B'], explanation: 'EKS Managed Node Groups provision EC2 instances, manage Auto Scaling Groups, and handle node updates (including cordoning, draining, and replacing nodes). Reduces operational overhead compared to self-managed nodes.', distractors: { A: 'Self-managed nodes require customers to handle AMI updates, patching, and lifecycle management manually.', C: 'Fargate profiles eliminate node management entirely — but have limitations (no DaemonSets, some addons).', D: 'AWS Batch is a separate service for batch workloads — not EKS node management.' } },
  { id: 'd3-svc-007', domain: 3, topics: ['Lambda', 'event source mapping', 'SQS'], type: 'single', stem: 'A Lambda function processes SQS messages. During high load, messages accumulate faster than Lambda processes them. What Lambda feature helps scale processing?', options: [{ id: 'A', text: 'Lambda reserved concurrency — limit the function to 5 concurrent executions' }, { id: 'B', text: 'Event source mapping scaling — Lambda automatically scales the number of concurrent pollers (up to 1,000 concurrent executions per event source mapping)' }, { id: 'C', text: 'Enable SQS long polling only' }, { id: 'D', text: 'Increase SQS message visibility timeout' }], correct: ['B'], explanation: 'For SQS event source mappings, Lambda scales concurrency up to 1,000 concurrent executions (5 concurrent pollers × 200 batches each). Lambda scales up by adding poller processes as the queue depth grows. The scaling is automatic.', distractors: { A: 'Reserved concurrency limits (not scales) processing — the wrong direction for backlog recovery.', C: 'Long polling reduces empty receives — doesn\'t change Lambda scaling behavior.', D: 'Visibility timeout affects message redelivery timing — not Lambda processing throughput.' } },
  { id: 'd3-svc-008', domain: 3, topics: ['ECS', 'service auto scaling', 'target tracking'], type: 'single', stem: 'An ECS service needs to scale based on CPU utilization. When CPU exceeds 70%, more tasks should launch. What auto scaling policy achieves this?', options: [{ id: 'A', text: 'Schedule-based auto scaling' }, { id: 'B', text: 'Target tracking scaling policy targeting ECSServiceAverageCPUUtilization at 70% — auto adjusts task count to maintain target CPU' }, { id: 'C', text: 'Step scaling policy with manual thresholds' }, { id: 'D', text: 'Capacity provider strategies' }], correct: ['B'], explanation: 'ECS Service Auto Scaling target tracking policy monitors a metric (e.g., ECSServiceAverageCPUUtilization) and automatically scales task count to maintain the target. When CPU exceeds 70%, scale out; when below, scale in.', distractors: { A: 'Scheduled scaling is for predictable traffic patterns — not reactive to real-time CPU utilization.', C: 'Step scaling works but target tracking is simpler and self-adjusting — preferred for CPU-based scaling.', D: 'Capacity providers control which EC2/Fargate capacity type to use — not scaling based on CPU metrics.' } },
  { id: 'd3-svc-009', domain: 3, topics: ['Lambda', 'ephemeral storage', '/tmp'], type: 'single', stem: 'A Lambda function needs to download and process a large file (800 MB) locally during execution. The default /tmp storage is 512 MB. What is the solution?', options: [{ id: 'A', text: 'Process the file in-memory using Python streams' }, { id: 'B', text: 'Configure Lambda ephemeral storage up to 10 GB — configurable /tmp storage from 512 MB to 10 GB' }, { id: 'C', text: 'Mount an EFS filesystem to Lambda for temporary files' }, { id: 'D', text: 'Use Lambda Layer for the large file' }], correct: ['B'], explanation: 'Lambda ephemeral storage (/tmp) is configurable from 512 MB to 10 GB. Configure the desired size in the function configuration. Cost: $0.0000000309/GB-second above 512 MB. Ideal for temporary large file processing.', distractors: { A: 'In-memory processing requires even more memory allocation — likely more expensive and still limited.', C: 'EFS mounts provide persistent storage — useful but requires VPC and higher latency than local /tmp.', D: 'Lambda Layers are deployment packages — not runtime scratch space for file processing.' } },
  { id: 'd3-svc-010', domain: 3, topics: ['ECS', 'Fargate', 'networking', 'awsvpc'], type: 'single', stem: 'Each ECS Fargate task needs its own security group and private IP address for fine-grained network control. What network mode supports this?', options: [{ id: 'A', text: 'Bridge network mode' }, { id: 'B', text: 'awsvpc network mode — each task gets its own ENI, private IP address, and security group' }, { id: 'C', text: 'Host network mode' }, { id: 'D', text: 'Overlay network mode (Docker Swarm)' }], correct: ['B'], explanation: 'awsvpc mode provides each ECS task (Fargate or EC2) its own Elastic Network Interface (ENI), private IP, and security group — same networking as EC2 instances. Required for Fargate. Enables task-level network isolation.', distractors: { A: 'Bridge mode shares the host\'s network namespace — tasks share security groups with the host EC2 instance.', C: 'Host mode uses the EC2 host\'s network directly — no task isolation; not supported in Fargate.', D: 'Overlay (Docker Swarm) is not an ECS network mode.' } },
  { id: 'd3-svc-011', domain: 3, topics: ['Lambda', 'destinations', 'async'], type: 'single', stem: 'An asynchronous Lambda function should route successful results to an SQS queue and failed results (after retries) to an SNS topic for alerting. What Lambda feature enables this routing?', options: [{ id: 'A', text: 'Lambda DLQ for all outcomes' }, { id: 'B', text: 'Lambda Destinations — configure separate On Success and On Failure destinations (SQS, SNS, Lambda, EventBridge)' }, { id: 'C', text: 'Lambda error handling in code' }, { id: 'D', text: 'CloudWatch alarm on error metric' }], correct: ['B'], explanation: 'Lambda Destinations route asynchronous invocation results: On Success sends to a destination (SQS, SNS, EventBridge, or another Lambda) when the function succeeds. On Failure routes failures after all retries are exhausted. More flexible than DLQ (which only handles failures).', distractors: { A: 'DLQ captures failed invocations only — doesn\'t route successful results.', C: 'Code-level error handling adds complexity and requires code changes — Destinations are configuration-only.', D: 'CloudWatch alarms trigger reactive actions — not real-time routing of Lambda outcomes.' } },
  { id: 'd3-svc-012', domain: 3, topics: ['EKS', 'Fargate', 'serverless Kubernetes'], type: 'single', stem: 'A team wants to run Kubernetes pods without managing EC2 worker nodes. What provides serverless Kubernetes pod execution?', options: [{ id: 'A', text: 'EKS Managed Node Groups (still requires node management)' }, { id: 'B', text: 'EKS Fargate profiles — pods matching namespace/label selectors run on Fargate without EC2 nodes' }, { id: 'C', text: 'ECS Fargate (not Kubernetes)' }, { id: 'D', text: 'AWS Batch with Kubernetes' }], correct: ['B'], explanation: 'EKS Fargate profiles define which pods (by namespace and label selectors) run on Fargate. AWS manages the underlying infrastructure. No EC2 nodes to patch, scale, or manage for those pods. Limitations: no DaemonSets, no privileged containers.', distractors: { A: 'Managed Node Groups reduce node management but still require EC2 instances.', C: 'ECS Fargate is for ECS tasks — not Kubernetes pods.', D: 'AWS Batch is a separate service for batch workloads — not Kubernetes.' } },
  { id: 'd3-svc-013', domain: 3, topics: ['Lambda', 'layers', 'shared libraries'], type: 'single', stem: 'Three Lambda functions all use the same 40 MB data processing library. Each function currently packages the library in its own ZIP. What reduces redundancy and deployment package sizes?', options: [{ id: 'A', text: 'Inline the library code into each function' }, { id: 'B', text: 'Create a Lambda Layer with the shared library — all three functions reference the layer; library is cached and not re-downloaded per function' }, { id: 'C', text: 'Store the library in S3 and import at startup' }, { id: 'D', text: 'Deploy as a monolithic function' }], correct: ['B'], explanation: 'Lambda Layers package shared code/dependencies. Functions reference layers by ARN; the layer is mounted to /opt in the execution environment. Up to 5 layers per function (total size limit 250 MB unzipped). Reduces deployment package duplication and enables centralized library updates.', distractors: { A: 'Inlining duplicates the code in each function — the opposite of reducing redundancy.', C: 'S3 downloads at startup increase cold start time and add latency — layers are pre-mounted.', D: 'Monolithic function combines unrelated logic — not appropriate for independent Lambda functions.' } },
  { id: 'd3-svc-014', domain: 3, topics: ['Step Functions', 'orchestration', 'performance'], type: 'single', stem: 'A workflow processes orders through 6 steps: validate, check inventory, charge payment, fulfill, notify, and archive. Steps need to run in sequence with state passed between them. What service orchestrates this workflow with retry logic?', options: [{ id: 'A', text: 'Lambda chaining — each function invokes the next' }, { id: 'B', text: 'AWS Step Functions — state machine defines workflow; manages state, retries, and error handling between Lambda function steps' }, { id: 'C', text: 'SQS chaining — one queue per step' }, { id: 'D', text: 'EventBridge rules with Lambda targets' }], correct: ['B'], explanation: 'Step Functions provides a managed state machine for workflow orchestration. Define workflow steps, transitions, retry policies, and error handling in JSON/YAML. State is automatically passed between steps. Visual workflow debugging in the console.', distractors: { A: 'Lambda chaining (each function calls the next) creates tight coupling and brittle error handling — Step Functions manages this externally.', C: 'SQS chaining requires a Lambda consumer per queue — complex and lacks state visibility.', D: 'EventBridge rules trigger events — not sequential workflow orchestration with state.' } },
  { id: 'd3-svc-015', domain: 3, topics: ['Lambda', 'timeout', 'async patterns'], type: 'single', stem: 'A Lambda function triggers a long-running process that takes 20 minutes. Lambda has a 15-minute maximum timeout. What architectural pattern handles this?', options: [{ id: 'A', text: 'Increase Lambda timeout to 20 minutes' }, { id: 'B', text: 'Use Lambda to start an ECS Fargate task or Step Functions workflow; Lambda returns immediately and the long process runs outside Lambda\'s timeout limit' }, { id: 'C', text: 'Split the process into 5 functions × 4 minutes each' }, { id: 'D', text: 'Use Lambda@Edge with 30-second limit' }], correct: ['B'], explanation: 'Lambda\'s hard maximum is 15 minutes. For longer workloads: trigger an ECS task (no time limit), a Step Functions Express/Standard workflow, a Batch job, or an EC2 process. Lambda fires the trigger and returns — the long process runs asynchronously.', distractors: { A: 'Lambda maximum timeout is 15 minutes — it cannot be increased beyond this.', C: 'Splitting into sequential 4-minute functions requires the orchestration problem to be solved separately — not simpler.', D: 'Lambda@Edge has a 5-second (viewer) or 30-second (origin) limit — far less than 15 minutes.' } },
  { id: 'd3-svc-016', domain: 3, topics: ['ECS', 'Fargate Spot', 'cost'], type: 'single', stem: 'An ECS workload runs batch processing jobs that can tolerate interruptions with graceful shutdown. What Fargate configuration reduces cost significantly?', options: [{ id: 'A', text: 'Fargate Compute Savings Plans' }, { id: 'B', text: 'Fargate Spot — runs tasks on spare capacity at up to 70% discount; tasks receive 2-minute interruption notice before termination' }, { id: 'C', text: 'Fargate with reserved capacity' }, { id: 'D', text: 'On-Demand EC2 with ECS' }], correct: ['B'], explanation: 'Fargate Spot uses spare Fargate capacity at up to 70% discount vs. on-demand Fargate. Tasks receive a 2-minute warning via ECS task state change event before interruption. Applications must handle graceful shutdown within that window.', distractors: { A: 'Fargate Compute Savings Plans provide 1-year commitment discounts — Fargate Spot provides larger discounts for interruptible workloads.', C: 'Fargate reserved capacity doesn\'t exist as a distinct product — Savings Plans are the commitment option.', D: 'On-Demand EC2 eliminates Fargate management benefits and doesn\'t provide the Spot discount.' } },
  { id: 'd3-svc-017', domain: 3, topics: ['Lambda', 'event source', 'DynamoDB Streams'], type: 'single', stem: 'A Lambda function must process DynamoDB Streams events in order for each partition key. What configuration ensures ordering?', options: [{ id: 'A', text: 'Lambda processes all shard records in parallel' }, { id: 'B', text: 'Lambda event source mapping processes each shard sequentially — records within a shard are ordered; parallelization factor can process multiple batches per shard concurrently' }, { id: 'C', text: 'Configure DynamoDB Streams to sort records by timestamp' }, { id: 'D', text: 'Set Lambda concurrency to 1' }], correct: ['B'], explanation: 'DynamoDB Streams records for a partition key always land in the same shard. Lambda processes each shard sequentially by default, preserving order within a shard. The parallelization factor (1-10) can process multiple batches per shard concurrently while maintaining per-batch order.', distractors: { A: 'Records within a shard are processed sequentially — only different shards are processed in parallel.', C: 'DynamoDB Streams doesn\'t provide timestamp sorting — shards maintain write order per partition key.', D: 'Lambda concurrency=1 would process all DynamoDB records sequentially globally — incorrect and a performance bottleneck.' } },
  { id: 'd3-svc-018', domain: 3, topics: ['ECS', 'service discovery', 'Cloud Map'], type: 'single', stem: 'Microservices in ECS need to discover each other by service name (not IP) and connect directly without a load balancer. What provides service discovery for ECS?', options: [{ id: 'A', text: 'Hardcode service IP addresses in environment variables' }, { id: 'B', text: 'AWS Cloud Map integration with ECS service discovery — registers tasks in Route 53 Private Hosted Zone; services resolve by DNS name' }, { id: 'C', text: 'ALB with target groups per service' }, { id: 'D', text: 'API Gateway for inter-service calls' }], correct: ['B'], explanation: 'ECS Service Discovery integrates with AWS Cloud Map. When tasks start, they register DNS records in a Route 53 private hosted zone. Other services resolve the service name via DNS to get task IPs directly — no load balancer needed for east-west traffic.', distractors: { A: 'Hardcoded IPs break when tasks are replaced — ECS task IPs change on every restart.', C: 'ALB adds latency and cost for east-west traffic; Cloud Map provides direct service-to-service DNS resolution.', D: 'API Gateway is for external API access — not internal microservice discovery.' } },
  { id: 'd3-svc-019', domain: 3, topics: ['Lambda', 'function URL', 'direct invoke'], type: 'single', stem: 'A Lambda function needs to be invoked via HTTPS directly without an API Gateway. What provides a dedicated HTTPS endpoint for a Lambda function?', options: [{ id: 'A', text: 'ALB with Lambda target group' }, { id: 'B', text: 'Lambda Function URLs — a built-in HTTPS endpoint for the function; supports Auth (IAM) or None, and CORS configuration' }, { id: 'C', text: 'Lambda@Edge' }, { id: 'D', text: 'CloudFront with Lambda origin' }], correct: ['B'], explanation: 'Lambda Function URLs provide a dedicated HTTPS endpoint (format: https://<url-id>.lambda-url.<region>.on.aws). Supports IAM authentication or no authentication. Useful for webhooks and simple APIs without API Gateway overhead.', distractors: { A: 'ALB with Lambda target works but adds cost and routing configuration — Function URL is simpler for direct HTTPS access.', C: 'Lambda@Edge executes at CloudFront edge — it\'s not a standalone HTTPS endpoint.', D: 'CloudFront with Lambda origin is valid but adds CDN complexity and cost for a simple HTTPS endpoint use case.' } },
  { id: 'd3-svc-020', domain: 3, topics: ['EKS', 'Cluster Autoscaler', 'Karpenter'], type: 'single', stem: 'An EKS cluster needs to scale EC2 nodes quickly (within seconds) based on pending pods, considering pod resource requirements for right-sized node selection. What AWS-native solution provides faster, cost-optimized node provisioning?', options: [{ id: 'A', text: 'Kubernetes Cluster Autoscaler with managed node groups' }, { id: 'B', text: 'Karpenter — AWS-native autoscaler that provisions right-sized instances directly based on pod requirements; faster than Cluster Autoscaler' }, { id: 'C', text: 'Manual EC2 Auto Scaling' }, { id: 'D', text: 'Fargate only — eliminate node management entirely' }], correct: ['B'], explanation: 'Karpenter is an open-source, AWS-native node provisioner. It watches for pending pods and provisions right-sized EC2 instances directly (no need for pre-defined node groups). Faster provisioning, better bin packing, supports Spot diversification, and consolidates underutilized nodes.', distractors: { A: 'Cluster Autoscaler works but is slower (scales at node group level) and less flexible than Karpenter.', C: 'Manual EC2 scaling ignores pod requirements — results in over/under-provisioning.', D: 'Fargate has limitations (no DaemonSets) and is more expensive for predictable workloads.' } },
  { id: 'd3-svc-021', domain: 3, topics: ['Lambda', 'SnapStart', 'Java'], type: 'single', stem: 'Java Lambda functions have 3+ second cold starts due to JVM initialization and application startup. What Lambda feature specifically addresses Java cold start performance?', options: [{ id: 'A', text: 'Provisioned Concurrency' }, { id: 'B', text: 'Lambda SnapStart for Java — takes a snapshot of the initialized execution environment; restores from snapshot on cold start instead of full initialization' }, { id: 'C', text: 'Increasing Lambda memory to 10 GB' }, { id: 'D', text: 'Switching to GraalVM native image' }], correct: ['B'], explanation: 'Lambda SnapStart (Java 11+) takes a snapshot of the initialized execution environment after the init phase completes. Cold starts resume from this snapshot (milliseconds) instead of re-running the full JVM startup. Up to 10x cold start improvement.', distractors: { A: 'Provisioned Concurrency eliminates cold starts by pre-warming environments — SnapStart is specifically optimized for Java init overhead and is lower cost.', C: 'More memory speeds up init but doesn\'t eliminate the JVM startup overhead.', D: 'GraalVM native image requires recompilation and has its own trade-offs — SnapStart works with standard JVM Java.' } },
  { id: 'd3-svc-022', domain: 3, topics: ['ECS', 'task placement', 'spread'], type: 'single', stem: 'An ECS cluster runs tasks on EC2 instances across multiple AZs. To maximize availability, tasks should be spread across AZs and then across instances. What task placement strategy achieves this?', options: [{ id: 'A', text: 'Binpack strategy — maximize instance utilization' }, { id: 'B', text: 'Spread strategy with availability zone attribute, then instance ID — distributes tasks across AZs first, then balances across instances within each AZ' }, { id: 'C', text: 'Random placement strategy' }, { id: 'D', text: 'Fargate (no placement strategy needed)' }], correct: ['B'], explanation: 'ECS task placement spread strategy with attribute:ecs.availability-zone distributes across AZs. Combine with a second spread by instanceId to balance within each AZ. This maximizes fault tolerance against both instance and AZ failures.', distractors: { A: 'Binpack consolidates tasks on fewer instances to reduce cost — the opposite goal of AZ spread for availability.', C: 'Random placement doesn\'t guarantee AZ distribution.', D: 'Fargate doesn\'t have task placement strategies — only EC2 launch type has placement strategies.' } },
  { id: 'd3-svc-023', domain: 3, topics: ['Lambda', 'efs mount', 'shared state'], type: 'single', stem: 'Multiple Lambda function invocations need to read and write shared files during execution. Lambda /tmp is local to each execution environment. What provides shared persistent file access?', options: [{ id: 'A', text: 'Use S3 for all file operations' }, { id: 'B', text: 'Mount an EFS filesystem to Lambda — multiple concurrent Lambda invocations can read/write the same EFS filesystem' }, { id: 'C', text: 'Use DynamoDB for file storage' }, { id: 'D', text: 'Use ElastiCache for file caching' }], correct: ['B'], explanation: 'Lambda supports mounting EFS filesystems via access points. The Lambda function must be in a VPC with connectivity to EFS. Multiple concurrent Lambda invocations share the same EFS filesystem — ideal for ML model files, shared datasets, and media files.', distractors: { A: 'S3 works for many use cases but requires S3 API calls — EFS provides POSIX file system semantics with local-file APIs.', C: 'DynamoDB is a key-value/document store — not a file system.', D: 'ElastiCache is an in-memory cache — not persistent file storage for large files.' } },
  { id: 'd3-svc-024', domain: 3, topics: ['ECR', 'container registry', 'performance'], type: 'single', stem: 'ECS task launch time is slow because container images are pulled from ECR across regions. How can image pull latency be reduced?', options: [{ id: 'A', text: 'Increase ECS task CPU' }, { id: 'B', text: 'Use ECR in the same region as ECS and enable ECR pull-through cache — optionally use image caching on EC2 launch type' }, { id: 'C', text: 'Use Docker Hub instead of ECR' }, { id: 'D', text: 'Store images in S3' }], correct: ['B'], explanation: 'Keep ECR and ECS in the same AWS region to avoid cross-region pull latency. Enable ECR pull-through cache for public registries. For EC2 launch type, pre-pull images to warm the Docker daemon cache on instances. Use image layer caching to only pull changed layers.', distractors: { A: 'More CPU doesn\'t speed up network-bound image downloads.', C: 'Docker Hub is public internet — higher latency and potential rate limits vs. private ECR.', D: 'Container images are stored as OCI/Docker format — S3 doesn\'t serve images to Docker daemons directly.' } },
  { id: 'd3-svc-025', domain: 3, topics: ['Lambda', 'concurrency', 'burst'], type: 'single', stem: 'A Lambda function goes from 0 to 10,000 concurrent requests suddenly. What is the initial scaling behavior?', options: [{ id: 'A', text: 'Lambda immediately scales to 10,000 concurrent executions' }, { id: 'B', text: 'Lambda scales from an initial burst limit (500-3,000 depending on region) then adds 500 concurrent executions per minute until the limit is reached' }, { id: 'C', text: 'Lambda scales linearly with a maximum of 100 new executions per minute' }, { id: 'D', text: 'Lambda is limited to 100 concurrent executions until warm-up completes' }], correct: ['B'], explanation: 'Lambda burst scaling: initial burst capacity (500-3,000 per region) can be reached immediately. After the initial burst, Lambda adds 500 concurrent executions per minute until reaching the account limit. Requests exceeding available capacity are throttled.', distractors: { A: 'Lambda has burst limits — immediate scale to 10,000 is not guaranteed.', C: '100 per minute is not the correct burst scaling rate — Lambda scales much faster.', D: '100 concurrent is not a warm-up limit — Lambda scales from the initial burst capacity.' } },
  { id: 'd3-svc-026', domain: 3, topics: ['App Runner', 'serverless containers'], type: 'single', stem: 'A developer wants to deploy a containerized web application without managing any infrastructure, load balancers, or auto scaling configuration. What fully managed service handles this?', options: [{ id: 'A', text: 'ECS with Fargate and ALB (still requires manual configuration)' }, { id: 'B', text: 'AWS App Runner — fully managed service: provide a container image or source code; App Runner handles build, deploy, scaling, load balancing, and TLS' }, { id: 'C', text: 'Elastic Beanstalk for containers' }, { id: 'D', text: 'Lambda with container images' }], correct: ['B'], explanation: 'App Runner is fully managed for containerized web apps. No VPC, load balancer, or auto scaling configuration. Connect a GitHub repo or ECR image; App Runner builds, deploys, manages TLS, scales based on traffic, and scales to zero when idle (optionally).', distractors: { A: 'ECS Fargate + ALB requires VPC, subnets, listener rules, task definitions — significant configuration.', C: 'Elastic Beanstalk still requires choosing load balancer type, instance type, and VPC settings.', D: 'Lambda has a 15-min timeout and 10 GB memory limit — less appropriate for traditional web server applications.' } },
  { id: 'd3-svc-027', domain: 3, topics: ['Lambda', 'power tuning', 'optimization'], type: 'single', stem: 'A Lambda function costs $50/month. The team wants to find the optimal memory setting that minimizes cost (duration × memory). What approach identifies the optimal configuration?', options: [{ id: 'A', text: 'Try each memory setting manually' }, { id: 'B', text: 'Use AWS Lambda Power Tuning (open-source Step Functions state machine) — runs the function at multiple memory settings and plots cost/performance trade-offs' }, { id: 'C', text: 'Set memory to maximum (10 GB) for fastest execution' }, { id: 'D', text: 'Use CloudWatch logs to estimate optimal memory' }], correct: ['B'], explanation: 'AWS Lambda Power Tuning is an open-source tool (deployed as Step Functions). It runs the function at multiple memory configurations, measures duration and cost, and visualizes the results. Helps find the "sweet spot" between speed and cost.', distractors: { A: 'Manual testing is slow and error-prone — Power Tuning automates testing across all memory settings.', C: 'Maximum memory costs more per GB-second — often not optimal unless the function is CPU-bound.', D: 'CloudWatch logs show duration but not the comparative cost across memory settings.' } },
  { id: 'd3-svc-028', domain: 3, topics: ['ECS', 'sidecar', 'Fluent Bit'], type: 'single', stem: 'ECS tasks need to send logs to multiple destinations (CloudWatch, S3, and a third-party service) without modifying application code. What pattern enables this?', options: [{ id: 'A', text: 'Send logs directly from the application to each destination' }, { id: 'B', text: 'Sidecar container pattern with Fluent Bit — the application logs to stdout; Fluent Bit sidecar captures and routes to multiple destinations' }, { id: 'C', text: 'CloudWatch agent on the EC2 host' }, { id: 'D', text: 'ECS FireLens — managed log routing using Fluent Bit/Fluentd as a sidecar with no code changes' }], correct: ['D'], explanation: 'ECS FireLens integrates Fluent Bit or Fluentd as a sidecar for log routing. No application code changes needed — configure log destinations in the task definition. Routes to CloudWatch, S3, Kinesis, Datadog, and more. The answer here is FireLens specifically, not manual sidecar configuration.', distractors: { A: 'Application-level multi-destination logging adds dependencies and couples the application to logging infrastructure.', B: 'ECS FireLens is the AWS-managed version of this — it\'s the specific AWS feature for this use case.', C: 'CloudWatch agent on the EC2 host doesn\'t capture container stdout/stderr routing without additional configuration.' } },
  { id: 'd3-svc-029', domain: 3, topics: ['Lambda', 'extensions', 'observability'], type: 'single', stem: 'A company uses a third-party observability tool (Datadog, New Relic) for Lambda monitoring. They need telemetry data sent to the tool without modifying Lambda function code. What mechanism supports this?', options: [{ id: 'A', text: 'Add SDK calls to each Lambda function' }, { id: 'B', text: 'Lambda Extensions — external extensions run in the Lambda execution environment alongside the function; send telemetry to external tools' }, { id: 'C', text: 'CloudWatch Logs subscription filter to forward to third-party' }, { id: 'D', text: 'Lambda Layers with instrumentation code' }], correct: ['B'], explanation: 'Lambda Extensions allow external processes to run alongside the Lambda function in the same execution environment. Third-party observability tools provide extensions that intercept telemetry, logs, and metrics and send them to external platforms without code changes.', distractors: { A: 'Adding SDK calls modifies every function — the opposite of code-change-free integration.', C: 'CloudWatch Logs subscription works but adds latency — Extensions operate at the Lambda level with lower latency.', D: 'Layers with instrumentation code requires code changes to instrument each function.' } },
  { id: 'd3-svc-030', domain: 3, topics: ['ECS', 'Fargate', 'GPU'], type: 'single', stem: 'An ML inference workload needs to run in containers and requires GPU acceleration. Does Fargate support GPU?', options: [{ id: 'A', text: 'Yes — Fargate supports GPU instances' }, { id: 'B', text: 'No — Fargate does not support GPU; use ECS on EC2 with GPU-enabled instance types (p3, g4) instead' }, { id: 'C', text: 'Yes, with Fargate Spot only' }, { id: 'D', text: 'Yes — through EKS Fargate profiles' }], correct: ['B'], explanation: 'Fargate is serverless and doesn\'t expose GPU hardware. For GPU containerized workloads, use ECS with EC2 launch type on GPU-enabled instances (p3.2xlarge, g4dn.xlarge, etc.) or EKS with GPU worker nodes. AWS also offers SageMaker for ML inference.', distractors: { A: 'Fargate does not support GPU — this is a known limitation.', C: 'Fargate Spot doesn\'t add GPU support.', D: 'EKS Fargate profiles also don\'t support GPU.' } },
  { id: 'd3-svc-031', domain: 3, topics: ['Lambda', 'response streaming', 'performance'], type: 'single', stem: 'A Lambda function generates a large HTML response (5 MB). Users must wait for the entire response before seeing anything. What Lambda capability allows sending data to clients progressively?', options: [{ id: 'A', text: 'Increase Lambda payload limit' }, { id: 'B', text: 'Lambda response streaming — stream partial results progressively; clients start receiving data before the function completes' }, { id: 'C', text: 'Use S3 to store the response and return a presigned URL' }, { id: 'D', text: 'Increase Lambda timeout' }], correct: ['B'], explanation: 'Lambda response streaming allows functions to stream responses progressively. First bytes reach the client immediately without waiting for the full response. Supports responses up to 20 MB (vs. 6 MB synchronous limit). Requires Function URL or streaming-compatible API Gateway.', distractors: { A: 'Lambda synchronous payload limit is 6 MB — streaming circumvents this but is the correct answer.', C: 'S3 presigned URL adds a round trip — streaming is for real-time progressive delivery.', D: 'Timeout increase allows longer execution — doesn\'t enable progressive streaming to clients.' } },
  { id: 'd3-svc-032', domain: 3, topics: ['ECS', 'capacity providers', 'Spot'], type: 'single', stem: 'An ECS cluster should automatically use On-Demand EC2 for a baseline of 2 tasks and Spot EC2 for all additional tasks to minimize cost while maintaining availability. What ECS feature enables this mixed capacity strategy?', options: [{ id: 'A', text: 'Two separate ECS services — one On-Demand, one Spot' }, { id: 'B', text: 'ECS Capacity Providers with a capacity provider strategy — base=2 for On-Demand, weight for Spot handles overflow' }, { id: 'C', text: 'Manual scaling scripts' }, { id: 'D', text: 'ECS Service Auto Scaling' }], correct: ['B'], explanation: 'ECS Capacity Providers with managed scaling define the mix. Set base=2 on the On-Demand capacity provider (always runs 2 tasks minimum there) and weight=1 on the Spot capacity provider. Additional tasks scale onto Spot. ECS managed scaling handles the EC2 Auto Scaling Groups automatically.', distractors: { A: 'Two separate services split the workload rather than providing a unified scaling strategy.', C: 'Manual scripts require ongoing maintenance and don\'t respond to demand changes.', D: 'Service Auto Scaling scales task count — not the capacity type mix.' } },
  { id: 'd3-svc-033', domain: 3, topics: ['Lambda', 'ARM Graviton', 'cost'], type: 'single', stem: 'A Lambda function currently runs on x86. A team wants to reduce both cost and improve performance. What Lambda architectural option improves price-performance?', options: [{ id: 'A', text: 'Increase memory to reduce duration' }, { id: 'B', text: 'Switch Lambda to arm64 (Graviton2) architecture — provides up to 34% better price-performance; 20% cheaper per GB-second than x86' }, { id: 'C', text: 'Use Lambda@Edge instead' }, { id: 'D', text: 'Enable Provisioned Concurrency' }], correct: ['B'], explanation: 'Lambda arm64 (Graviton2) costs 20% less per GB-second and typically runs faster for compute-bound workloads. For interpreted languages (Python, Node.js), switching architecture requires no code changes — just a Lambda configuration change.', distractors: { A: 'More memory reduces duration but at a higher per-GB-second cost — often no net savings.', C: 'Lambda@Edge runs at CloudFront edge nodes — not a compute optimization for standard Lambda.', D: 'Provisioned Concurrency eliminates cold starts but increases cost by pre-allocating environments.' } },
  { id: 'd3-svc-034', domain: 3, topics: ['ECS', 'load balancer', 'ALB target'], type: 'single', stem: 'An ECS service uses awsvpc network mode with ALB. When a new task starts, how does it register with the ALB?', options: [{ id: 'A', text: 'Manually add the task IP to the target group' }, { id: 'B', text: 'ECS automatically registers task IPs with the ALB target group on task start and deregisters on task stop' }, { id: 'C', text: 'The ALB discovers tasks via DNS' }, { id: 'D', text: 'Tasks register themselves on startup' }], correct: ['B'], explanation: 'ECS integrates with ALB/NLB target groups automatically. When a task transitions to RUNNING, ECS registers the task\'s IP and port with the specified load balancer target group. On task stop, ECS deregisters it (respecting deregistration delay).', distractors: { A: 'Manual IP management is not required — ECS handles target registration automatically.', C: 'ALB uses direct IP routing to targets — not DNS discovery.', D: 'Target registration is handled by ECS, not by the application running in the container.' } },
  { id: 'd3-svc-035', domain: 3, topics: ['Lambda', 'code signing', 'security'], type: 'single', stem: 'A security policy requires that only trusted, cryptographically signed Lambda deployment packages can be deployed. What prevents unsigned code from running in Lambda?', options: [{ id: 'A', text: 'IAM policies restricting Lambda deployment' }, { id: 'B', text: 'Lambda code signing — functions configured with signing profiles reject deployments not signed by a trusted profile using AWS Signer' }, { id: 'C', text: 'S3 bucket policies for deployment packages' }, { id: 'D', text: 'VPC endpoint policies for Lambda' }], correct: ['B'], explanation: 'Lambda code signing uses AWS Signer to sign deployment packages. Functions configured with a code signing configuration reject deployments if the code is unsigned or signed by an untrusted authority. Provides supply-chain integrity for Lambda deployments.', distractors: { A: 'IAM policies control who can deploy — not whether the code itself is cryptographically signed.', C: 'S3 bucket policies control access to packages — not code signing verification.', D: 'VPC endpoint policies control network access — not code integrity.' } },
  { id: 'd3-svc-036', domain: 3, topics: ['Fargate', 'storage', 'ephemeral vs EFS'], type: 'single', stem: 'An ECS Fargate task needs persistent storage that survives task restarts and is shared between multiple tasks in the same service. What storage option provides this?', options: [{ id: 'A', text: 'Fargate ephemeral storage (20 GB default) — lost when the task stops' }, { id: 'B', text: 'Amazon EFS volume mounted to Fargate tasks — persists independently of task lifecycle; multiple tasks share the same filesystem' }, { id: 'C', text: 'EBS volume attached to Fargate task' }, { id: 'D', text: 'S3 synchronization on task start/stop' }], correct: ['B'], explanation: 'EFS integrates with Fargate tasks as a persistent volume. Mount the EFS filesystem in the task definition. Data persists across task restarts, replacements, and multiple concurrent tasks can read/write the same filesystem.', distractors: { A: 'Fargate ephemeral storage is lost when the task stops — not persistent.', C: 'EBS volumes cannot be attached to Fargate tasks — EBS requires EC2 instances.', D: 'S3 sync on start/stop adds latency and complexity — EFS provides native persistent filesystem semantics.' } },
  { id: 'd3-svc-037', domain: 3, topics: ['Lambda', 'VPC', 'cold start'], type: 'single', stem: 'Lambda functions in a VPC had cold starts significantly longer than non-VPC functions in 2019. Is this still true in 2023+?', options: [{ id: 'A', text: 'Yes — VPC Lambda still has minutes-long cold starts due to ENI creation' }, { id: 'B', text: 'No — since 2020, Lambda VPC cold starts are comparable to non-VPC; AWS pre-creates and reuses Hyperplane ENIs at scale' }, { id: 'C', text: 'Yes — VPC Lambda always takes 5+ seconds to cold start' }, { id: 'D', text: 'VPC Lambda doesn\'t exist — Lambda cannot join a VPC' }], correct: ['B'], explanation: 'The VPC cold start penalty was eliminated with AWS\'s Hyperplane ENI management (launched 2020). ENIs are pre-created and reused across Lambda functions. VPC Lambda cold starts are now similar to non-VPC Lambda cold starts.', distractors: { A: 'This was true before 2020 — the ENI creation bottleneck was removed with Hyperplane.', C: '5+ second cold starts for VPC Lambda are historical — no longer accurate.', D: 'Lambda supports VPC configuration — functions can access VPC resources like RDS and ElastiCache.' } },
  { id: 'd3-svc-038', domain: 3, topics: ['EKS', 'pod autoscaling', 'HPA'], type: 'single', stem: 'An EKS deployment needs to automatically scale the number of pods based on CPU utilization. What Kubernetes resource enables this?', options: [{ id: 'A', text: 'Kubernetes StatefulSet' }, { id: 'B', text: 'Horizontal Pod Autoscaler (HPA) — scales pod replicas based on metrics (CPU, memory, custom) to maintain target utilization' }, { id: 'C', text: 'Kubernetes DaemonSet' }, { id: 'D', text: 'Kubernetes Job' }], correct: ['B'], explanation: 'HPA monitors pod metrics (CPU, memory, or custom metrics via KEDA) and adjusts the replica count to maintain the target utilization. The metrics-server (or custom metrics adapter) provides the metrics to HPA. Works with Deployments, ReplicaSets, and StatefulSets.', distractors: { A: 'StatefulSet manages ordered pod deployment for stateful applications — not autoscaling based on metrics.', C: 'DaemonSet runs one pod per node — not workload autoscaling.', D: 'Job runs pods to completion — not a running service with autoscaling.' } },
  { id: 'd3-svc-039', domain: 3, topics: ['Lambda', 'dead letter queue', 'async retries'], type: 'single', stem: 'An asynchronous Lambda invocation fails after 2 automatic retries. Where should failed events go for investigation?', options: [{ id: 'A', text: 'Failed events are discarded' }, { id: 'B', text: 'Configure a Dead Letter Queue (DLQ) — SQS or SNS; Lambda sends failed events here after exhausting retries' }, { id: 'C', text: 'CloudWatch logs capture failed events automatically' }, { id: 'D', text: 'Lambda Destinations On Failure (more feature-rich than DLQ)' }], correct: ['D'], explanation: 'Lambda Destinations On Failure is the modern, preferred approach over DLQ. Destinations carry more context (including the function response/error) compared to DLQ which only receives the original payload. Configure an SQS, SNS, EventBridge, or Lambda destination for failures.', distractors: { A: 'Events are not discarded — Lambda retries 2 times (total 3 attempts) then sends to DLQ/Destination if configured.', B: 'DLQ works and is valid — Lambda Destinations is the more feature-rich modern replacement with additional context.', C: 'CloudWatch logs show error details for investigation but don\'t capture the event payload for replay.' } },
  { id: 'd3-svc-040', domain: 3, topics: ['ECS', 'blue/green', 'CodeDeploy'], type: 'single', stem: 'An ECS service needs zero-downtime deployments with the ability to instantly roll back by shifting traffic back to the old version. What deployment strategy supports this?', options: [{ id: 'A', text: 'Rolling update (default ECS strategy) — gradually replaces old tasks' }, { id: 'B', text: 'Blue/Green deployment with CodeDeploy — two identical environments; traffic shifts from blue (old) to green (new) on ALB; instant rollback by reverting traffic' }, { id: 'C', text: 'Recreate strategy — stop all old tasks then start new ones' }, { id: 'D', text: 'Canary deployment with weighted routing' }], correct: ['B'], explanation: 'ECS blue/green (CodeDeploy) creates a new "green" task set alongside "blue." Traffic shifts using ALB weighted target groups. Instant rollback: CodeDeploy re-routes 100% traffic back to blue. The green task set is terminated after bake time.', distractors: { A: 'Rolling updates gradually replace old tasks — rollback is slower (must roll forward or redeploy the old version).', C: 'Recreate causes downtime between stopping old tasks and starting new ones.', D: 'Canary deployments test a small traffic percentage on the new version — doesn\'t provide the instant full rollback that blue/green does.' } },
  { id: 'd3-svc-041', domain: 3, topics: ['Lambda', 'environment variables', 'configuration'], type: 'single', stem: 'Lambda environment variables contain a database password in plaintext. A security team flags this as a risk. What is the recommended approach for secrets in Lambda?', options: [{ id: 'A', text: 'Encrypt environment variables with Lambda KMS key' }, { id: 'B', text: 'Store secrets in AWS Secrets Manager; Lambda fetches them at runtime via SDK call or Lambda extension' }, { id: 'C', text: 'Base64-encode the password in the environment variable' }, { id: 'D', text: 'Use SSM Parameter Store SecureString with IAM restriction' }], correct: ['B'], explanation: 'AWS Secrets Manager is the recommended service for credentials. Lambda fetches secrets at runtime via the Secrets Manager SDK or Lambda extension (for automatic caching). Secrets are rotated without Lambda redeployment. B is preferred over D because Secrets Manager provides automatic rotation.', distractors: { A: 'KMS-encrypted environment variables are better than plaintext but the secret is still visible in the Lambda console — Secrets Manager provides better access control.', C: 'Base64 is encoding, not encryption — provides no security.', D: 'SSM Parameter Store SecureString is valid and less expensive — but Secrets Manager provides automatic rotation which is specifically called out for credentials.' } },
  { id: 'd3-svc-042', domain: 3, topics: ['ECS', 'health checks', 'task replacement'], type: 'single', stem: 'An ECS task is unhealthy — the application inside the container is running but returning errors. What two mechanisms detect task health independently?', options: [{ id: 'A', text: 'EC2 instance health check only' }, { id: 'B', text: 'Docker HEALTHCHECK in Dockerfile (container-level) + ALB target group health check (application-level) — ECS replaces tasks that fail Docker health checks' }, { id: 'C', text: 'CloudWatch agent health monitoring' }, { id: 'D', text: 'ECS Agent heartbeat only' }], correct: ['B'], explanation: 'Docker HEALTHCHECK runs inside the container and reports container health to ECS. ECS replaces unhealthy containers. ALB health checks test application-level HTTP responses — deregisters unhealthy targets before ECS replaces them. Two independent layers of health detection.', distractors: { A: 'EC2 instance health check detects host-level failures — not application-level container health.', C: 'CloudWatch agent provides OS-level metrics — not container application health checks.', D: 'ECS Agent heartbeat confirms the agent is running — not the application health inside the container.' } },
  { id: 'd3-svc-043', domain: 3, topics: ['Lambda', 'max payload', 'limits'], type: 'single', stem: 'A Lambda function is invoked synchronously with a payload of 7 MB. What happens?', options: [{ id: 'A', text: 'The invocation succeeds — Lambda supports up to 10 GB payloads' }, { id: 'B', text: 'The invocation fails — synchronous Lambda invocation payload limit is 6 MB (request + response combined)' }, { id: 'C', text: 'Lambda compresses the payload automatically' }, { id: 'D', text: 'The payload is stored in S3 automatically' }], correct: ['B'], explanation: 'Lambda synchronous invocation limit: 6 MB for request payload and 6 MB for response payload. 7 MB exceeds this limit. Workaround: store the data in S3, pass the S3 key to Lambda, and retrieve the data inside the function.', distractors: { A: 'Lambda has a 6 MB synchronous payload limit — not 10 GB.', C: 'Lambda doesn\'t auto-compress payloads — the caller is responsible.', D: 'Automatic S3 storage doesn\'t happen — the invocation simply fails with a 413 error.' } },
  { id: 'd3-svc-044', domain: 3, topics: ['ECS', 'secrets', 'Secrets Manager integration'], type: 'single', stem: 'An ECS task definition needs to inject a database password from Secrets Manager as an environment variable — without the application fetching it at runtime. How is this configured?', options: [{ id: 'A', text: 'Add the secret ARN directly in the task definition as an environment variable value' }, { id: 'B', text: 'Use the secrets parameter in the ECS task definition — ECS injects the secret value from Secrets Manager (or SSM Parameter Store) as an environment variable at task startup' }, { id: 'C', text: 'Store the secret in an ECS-specific secret store' }, { id: 'D', text: 'Bake the secret into the container image' }], correct: ['B'], explanation: 'ECS task definitions support a secrets field that references Secrets Manager ARNs or SSM Parameter Store paths. ECS fetches the secret value at task startup and injects it as an environment variable. The application sees a plain environment variable — no SDK calls needed.', distractors: { A: 'Putting the ARN as the environment variable value sends the ARN string to the application — not the secret value.', C: 'No ECS-specific secret store exists — Secrets Manager and SSM Parameter Store are the integrated options.', D: 'Baking secrets into container images is a security anti-pattern — secrets become part of the image layer history.' } },
  { id: 'd3-svc-045', domain: 3, topics: ['Lambda', 'invocation types', 'synchronous vs async'], type: 'single', stem: 'A web API calls Lambda synchronously and waits for the response. A batch job triggers Lambda asynchronously and doesn\'t need the response. What invocation types correspond to these scenarios?', options: [{ id: 'A', text: 'Both use the same RequestResponse invocation type' }, { id: 'B', text: 'Web API: RequestResponse (synchronous — waits for response); Batch job: Event (asynchronous — Lambda acknowledges receipt, processes independently)' }, { id: 'C', text: 'Web API uses DryRun; Batch job uses Event' }, { id: 'D', text: 'Both can use Event invocation type with polling' }], correct: ['B'], explanation: 'Lambda invocation types: RequestResponse (synchronous) — connection held open until function completes, response returned to caller. Event (asynchronous) — Lambda queues the event and returns 202 immediately, processes in background. DryRun validates permissions without executing.', distractors: { A: 'Different patterns use different invocation types — synchronous vs. asynchronous is a fundamental Lambda concept.', C: 'DryRun tests permissions — it doesn\'t invoke the function handler.', D: 'Event invocation doesn\'t return function output to the caller — the web API would need RequestResponse.' } },
]
